```js
// --- Collision resolution (bricks) ----------------------------------------

// True if the ball's edge crossed one of the brick's face planes during the
// step. Swept by construction: a brick whose face the ball crossed is a hit
// even if the ball's final position no longer overlaps it (no tunneling).
function crossedFace(ball, brick, prevX, prevY) {
  const result = { x: false, y: false };
  const prevTop = prevY - ball.r;
  const nowTop = ball.y - ball.r;
  const prevBottom = prevY + ball.r;
  const nowBottom = ball.y + ball.r;
  const prevLeft = prevX - ball.r;
  const nowLeft = ball.x - ball.r;
  const prevRight = prevX + ball.r;
  const nowRight = ball.x + ball.r;
  if (prevBottom <= brick.y && nowBottom > brick.y) result.y = true;        // top face
  if (prevTop >= brick.y + brick.h && nowTop < brick.y + brick.h) result.y = true; // bottom face
  if (prevRight <= brick.x && nowRight > brick.x) result.x = true;          // left face
  if (prevLeft >= brick.x + brick.w && nowLeft < brick.x + brick.w) result.x = true; // right face
  return result;
}

// Overlap depths of the ball (as a box) against the brick, per axis.
function penetration(ball, brick) {
  return {
    x: Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r)),
    y: Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r)),
  };
}

// Resolves the ball against every brick it touched during the step: destroys
// and scores each touched brick once, then applies a SINGLE bounce — the axes
// whose faces were crossed (corner: both), falling back to the axis of
// smallest penetration when the ball was already overlapping at step start.
function resolveBricks(state, prevX, prevY) {
  const { ball, bricks } = state;
  const touched = bricks.filter((b) => b.alive && collides(ball, b));
  if (touched.length === 0) return;

  for (const brick of touched) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  let flipX = false;
  let flipY = false;
  for (const brick of touched) {
    const crossed = crossedFace(ball, brick, prevX, prevY);
    if (crossed.x) flipX = true;
    if (crossed.y) flipY = true;
  }
  if (!flipX && !flipY) {
    const pen = penetration(ball, touched[0]);
    if (pen.x < pen.y) flipX = true;
    else if (pen.y < pen.x) flipY = true;
    else flipX = flipY = true; // corner: equal penetration on both axes
  }

  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;

  // Push the ball back out, tangent to the face(s) it crossed.
  const first = touched[0];
  const crossed = crossedFace(ball, first, prevX, prevY);
  const pen = penetration(ball, first);
  if (flipX) {
    if (crossed.x) {
      if (prevX + ball.r <= first.x) ball.x = first.x - ball.r;
      else ball.x = first.x + first.w + ball.r;
    } else if (pen.x < pen.y || pen.x === pen.y) {
      // fallback: push along the smaller of the two overhangs
      if (ball.x + ball.r - first.x <= first.x + first.w - (ball.x - ball.r)) ball.x = first.x - ball.r;
      else ball.x = first.x + first.w + ball.r;
    }
  }
  ...
```

