// The face the ball crossed on a given axis: -1 (before the brick) or +1 (after).
// Returns the position that makes the ball tangent to that face.
function pushAxis(ball, brick, axis, prevX, prevY) {
  if (axis === 'x') {
    if (prevX + ball.r <= brick.x) return brick.x - ball.r;          // entered from the left
    if (prevX - ball.r >= brick.x + brick.w) return brick.x + brick.w + ball.r; // from the right
    // already overlapping on x at the previous position: smallest overhang
    const left = ball.x + ball.r - brick.x;
    const right = brick.x + brick.w - (ball.x - ball.r);
    return left <= right ? brick.x - ball.r : brick.x + brick.w + ball.r;
