edits.newText:
// --- Physics (movement + wall/paddle/brick bounces) -------------------------

// True if the ball's leading edge crossed one of the brick's face planes
// during the step. This is a swept test by construction: a brick whose face
// the ball crossed is a hit even when the final position no longer overlaps
// it, so no step — however long — can tunnel past it.
function crossedFace(ball, brick, prevX, prevY) {
  const result = { x: false, y: false };
  const prevTop = prevY - ball.r;
  const nowTop = ball.y - ball.r;
  const prevBottom = prevY + ball.r;
  const nowBottom = ball.y + ball.r;
  const prevLeft = prevX - ball.r;
  const nowLeft = ball.x - ball.r;
  const prevRight = prevX + ball.r;
  const nowRight = ball.x + ball.r;
  // Top face
  if (prevBottom <= brick.y && nowBottom > brick.y) result.y = true;
  // Bottom face
  if (prevTop >= brick.y + brick.h && nowTop < brick.y + brick.h) result.y = true;
  // Left face
  if (prevRight <= brick.x && nowRight > brick.x) result.x = true;
  // Right face
  if (prevLeft >= brick.x + brick.w && nowLeft < brick.x + brick.w) result.x = true;
  return result;
}

// Per-axis overlap of the ball (as a box) with the brick, in pixels.
function penetration(ball, brick) {
  return {
    x: Math.min(
      ball.x + ball.r - brick.x,
      brick.x + brick.w - (ball.x - ball.r),
    ),
    y: Math.min(
      ball.y + ball.r - brick.y,
      brick.y + brick.h - (ball.y - ball.r),
    ),
  };
}

// Position that makes the ball tangent to the brick on the given axis,
// pushed out through the face it crossed (fallback: the smallest overhang).
function pushOut(ball, brick, axis, prevX, prevY) {
  if (axis === 'x') {
    if (prevX + ball.r <= brick.x) return brick.x - ball.r;
    if (prevX - ball.r >= brick.x + brick.w) return brick.x + brick.w + ball.r;
    const pen = penetration(ball, brick);
    return ball.x + ball.r - brick.x <= brick.x + brick.w - (ball.x - ball.r)
      ? brick.x - ball.r
      : brick.x + brick.w + ball.r;
  }
  if (prevY + ball.r <= brick.y) return brick.y - ball.r;
  if (prevY - ball.r >= brick.y + brick.h) return brick.y + brick.h + ball.r;
  const pen = penetration(ball, brick);
  return ball.y + ball.r - brick.y <= brick.y + brick.h - (ball.y - ball.r)
    ? brick.y - ball.r
    : brick.y + brick.h + ball.r;
}

// Destroys every brick the ball touched during the step (each scored once),
// then applies a SINGLE bounce: the axes whose faces were crossed — a corner
// (both faces crossed, or equal penetration) flips both axes. This is what
// keeps a seam between two bricks from cancelling two `vy = -vy` and letting
// the ball through.
function resolveBricks(state, prevX, prevY) {
  const { ball, bricks } = state;
  const touched = bricks.filter((b) => b.alive && collides(ball, b));
  if (touched.length === 0) return;

  for (const brick of touched) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  let flipX = false;
  let flipY = false;
  for (const brick of touched) {
    const crossed = crossedFace(ball, brick, prevX, prevY);
    if (crossed.x) flipX = true;
    if (crossed.y) flipY = true;
  }
  if (!flipX && !flipY) {
    // The ball was already overlapping at the previous position (sticky or
    // corner approach): fall back to the axis of smallest penetration, and
    // treat equal penetration as a corner (both axes flip).
    const pen = penetration(ball, touched[0]);
    if (pen.x < pen.y) flipX = true;
    else if (pen.y < pen.x) flipY = true;
    else flipX = flipY = true;
  }

  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;

  const first = touched[0];
  if (flipX) ball.x = pushOut(ball, first, 'x', prevX, prevY);
  if (flipY) ball.y = pushOut(ball, first, 'y', prevX, prevY);
