// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks (scoring included).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: swept test — a ball whose bottom edge crossed the paddle top
  // plane during the step must bounce even if the step was long enough to
  // jump over the 12px capture band (tunneling).
  if (
    ball.vy > 0 &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    const prevBottom = prevY + ball.r;
    const nowBottom = ball.y + ball.r;
    const crossedTop = prevBottom <= paddle.y && nowBottom >= paddle.y;
    const inBand = nowBottom >= paddle.y && nowBottom <= paddle.y + paddle.h;
    if (crossedTop || inBand) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Bricks: swept per-face bounce + scoring, in pure logic.
  resolveBricks(state, prevX, prevY);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

