import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

edits.newText:
test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Brick collision: bounce, push-out, seam, faces, tunneling -------------
// (D1-D6 of .scratch/to_fix.md, since removed)

function singleBrick() {
  return { x: 100, y: 100, w: 72, h: 20, alive: true };
}

function stateWithBall(ball, bricks) {
  const state = createState(1);
  state.bricks = bricks;
  state.ball = { ...state.ball, ...ball };
  return state;
}

test('D1: ball bounces off the underside of a brick and exits it', () => {
  const brick = singleBrick();
  const state = stateWithBall({ x: 136, y: 128, vx: 0, vy: -260 }, [brick]);
  step(state, 1 / 60);
  assert.ok(state.ball.vy > 0, 'vy must flip upward -> downward');
  assert.equal(brick.alive, false, 'brick must be destroyed');
  assert.ok(
    state.ball.y - state.ball.r >= brick.y + brick.h,
    'ball must end outside the brick, below its bottom face',
  );
});

test('D2: a ball already overlapping a brick is pushed out (no sticky)', () => {
  const brick = singleBrick();
  // Ball top edge already 3px inside the brick's bottom face.
  const state = stateWithBall({ x: 136, y: 124, vx: 0, vy: -260 }, [brick]);
  step(state, 1 / 60);
  assert.ok(
    state.ball.y - state.ball.r >= brick.y + brick.h,
    'ball must be pushed fully outside the brick after one step',
  );
});

test('D3: seam — one bounce when descending onto the 8px gap between two bricks', () => {
  const state = createState(1);
  // Row 0: col3 = 244..316, col4 = 324..396; seam center x = 320, gap 8px
  // (< ball diameter 14, so the ball straddles both bricks at once).
  state.ball = { x: 320, y: 40, r: 7, vx: 0, vy: 260 };
  const c = state.bricks.find((b) => b.row === 0 && b.x === 244);
  const d = state.bricks.find((b) => b.row === 0 && b.x === 324);
  step(state, 0.05);
  assert.ok(state.ball.vy < 0, 'vy must flip exactly once (not twice)');
  assert.ok(
    state.ball.y + state.ball.r <= 48,
    'ball must be pushed back above the row',
  );
  assert.equal(c.alive, false, 'left brick of the seam is hit');
  assert.equal(d.alive, false, 'right brick of the seam is hit');
});

test('D4a: side hit flips vx, not vy', () => {
  const brick = singleBrick();
  // Ball 4px into the left face (x-pen 8.3 < y-pen 17), moving straight right.
  const state = stateWithBall({ x: 97, y: 110, vx: 260, vy: 0 }, [brick]);
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0, 'horizontal velocity must flip');
  assert.equal(state.ball.vy, 0, 'vertical velocity must stay 0');
});

test('D4b: equal penetration = corner, both axes flip', () => {
  const brick = singleBrick();
  // Symmetric 45° approach: 4px into x AND 4px into y at the start.
  const state = stateWithBall({ x: 97, y: 97, vx: 260, vy: 260 }, [brick]);
  step(state, 1 / 60);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'both axes flip');
});

test('D5: no tunneling at level 6 / dt=0.05 (35.5px > brick h 20 + 2r 14)', () => {
  for (const dt of [0.05, 1 / 60]) {
    const brick = singleBrick();
    const state = createState(6);
    state.bricks = [brick];
    state.ball = { x: 136, y: 128, r: 7, vx: 0, vy: -ballSpeed(6) };
    step(state, dt);
    assert.equal(brick.alive, false, `dt=${dt}: brick must be hit, not skipped`);
    assert.ok(state.ball.vy > 0, `dt=${dt}: ball must bounce down`);
    assert.ok(
      state.ball.y - state.ball.r >= brick.y + brick.h,
      `dt=${dt}: ball must end below the brick`,
    );
  }
});

test('D6: no paddle tunneling at dt=0.05 (13px step > 12px band)', () => {
  const state = createState(1);
  // Ball bottom edge 0.5px above the paddle top, falling fast.
  state.ball = {
    x: WIDTH / 2,
    y: PADDLE_Y - BALL_R - 0.5,
    r: 7,
    vx: 0,
    vy: 260,
  };
  step(state, 0.05);
  assert.ok(state.ball.vy < 0, 'ball must bounce off the paddle');
  assert.ok(
    state.ball.y + state.ball.r <= PADDLE_Y,
    'ball must end above the paddle top',
  );
});

